    # 键序：会话、结果、时刻、截止；会话/结果为 str，时刻/截止为 int。
    payload = {
        "会话": sid,
        "结果": result,
        "时刻": now_ms,
        "截止": deadline,
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

